// =========================================================================
// Strategy 2: single_row — preferred when 1024 < N <= 8192
// =========================================================================

template <typename dataType>
class AddLayerNormSingleRowKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
        GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float eps, float invN,
        int64_t biasFlag, int64_t additionalOut, int64_t dtypeFlag)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->eps = eps;
        this->invN = invN;
        this->biasFlag = biasFlag;
        this->additionalOut = additionalOut;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Ptr), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Ptr), static_cast<uint64_t>(M) * N);
        biasGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(biasPtr),
            (biasFlag == 2) ? static_cast<uint64_t>(M) * N : N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gammaPtr), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(betaPtr), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yPtr), static_cast<uint64_t>(M) * N);
        xAddOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xAddOutPtr),
                                   static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
            pipe.InitBuffer(betaBuf_, N * sizeof(dataType));
            pipe.InitBuffer(biasBuf_, N * sizeof(dataType));
            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            pipe.InitBuffer(centeredBuf_, N * sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
                pipe.InitBuffer(betaCastBuf_, N * sizeof(float));
                pipe.InitBuffer(biasCastBuf_, N * sizeof(float));
                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
                pipe.InitBuffer(xAddCastBuf_, N * sizeof(float));
            }

            // Pre-load gamma and beta
            gammaInLocal_ = gammaBuf_.Get<dataType>();
            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);

            betaInLocal_ = betaBuf_.Get<dataType>();
            LoadGmToUb(betaInLocal_, betaGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            PrepareInputTensorHelper<dataType>(betaLocal_, betaInLocal_, betaCastBuf_, N);

            // Pre-load bias if broadcast mode (biasFlag == 1)
            if (biasFlag == 1) {
                biasInLocal_ = biasBuf_.Get<dataType>();
                LoadGmToUb(biasInLocal_, biasGM_, static_cast<uint32_t>(N));
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();
                PrepareInputTensorHelper<dataType>(biasLocal_, biasInLocal_, biasCastBuf_, N);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(M, blockM)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX1(int32_t rowIdx)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x1InQueue_.EnQue(x1InLocal_);
    }

    __aicore__ inline void CopyInX2(int32_t rowIdx)
    {
        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x2InQueue_.EnQue(x2InLocal_);
    }

    __aicore__ inline void CopyInBias(int32_t rowIdx)
    {
        biasRowLocal_ = biasBuf_.Get<dataType>();
        LoadGmToUb(biasRowLocal_, biasGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        PrepareInputTensorHelper<dataType>(biasRowLocalF_, biasRowLocal_, biasCastBuf_, N);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void CopyOutXAdd(int32_t rowIdx)
    {
        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
        StoreUbToGm(xAddOutGM_[static_cast<uint64_t>(rowIdx) * N], xAddOutLocal_, static_cast<uint32_t>(N));
        xAddOutQueue_.FreeTensor(xAddOutLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        centeredLocal_ = centeredBuf_.Get<float>();

        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, N);
        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, N);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        // Step 1: x_add = x1 + x2
        AscendC::Add(yLocal_, x1Local_, x2Local_, N);

        // Step 2: add bias if present
        if (biasFlag == 1) {
            AscendC::Add(yLocal_, yLocal_, biasLocal_, N);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocalF_, N);
        }

        // Step 3: store x_add if needed
        if (additionalOut) {
            xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
            PrepareOutputTensorHelper<dataType>(xAddLocal_, xAddOutLocal_, xAddCastBuf_);
            AscendC::Duplicate(xAddLocal_, yLocal_, N, 1, 1, 8);
            AscendC::PipeBarrier<PIPE_V>();
            FinalizeOutputTensorHelper<dataType>(xAddOutLocal_, xAddLocal_, N);
            xAddOutQueue_.EnQue(xAddOutLocal_);
        }

        // Step 4: LayerNorm
        // mean = sum(y) / N
        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
        float meanVal = sumLocal_.GetValue(0) * invN;

        // Save y (centered = y - mean) in centered buffer, then compute var
        AscendC::Subs(centeredLocal_, yLocal_, meanVal, N);
        AscendC::Mul(yLocal_, centeredLocal_, centeredLocal_, N);
        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
        float varVal = sumLocal_.GetValue(0) * invN + eps;

        // inv_std = 1/sqrt(var)
        float invStd = 1.0f / sqrtf(varVal);

        // y = centered * inv_std * gamma + beta
        AscendC::Muls(yLocal_, centeredLocal_, invStd, N);
        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
        AscendC::Add(yLocal_, yLocal_, betaLocal_, N);
        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        CopyInX1(rowIdx);
        CopyInX2(rowIdx);
        if (biasFlag == 2) {
            CopyInBias(rowIdx);
        }
        ComputeRow();
        CopyOutY(rowIdx);
        if (additionalOut) {
            CopyOutXAdd(rowIdx);
        }
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    int64_t biasFlag = 0;
    int64_t additionalOut = 0;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> xAddOutGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> centeredBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xAddCastBuf_;

    AscendC::LocalTensor<dataType> gammaInLocal_;
    AscendC::LocalTensor<dataType> betaInLocal_;
    AscendC::LocalTensor<dataType> biasInLocal_;
    AscendC::LocalTensor<dataType> biasRowLocal_;
    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<dataType> xAddOutLocal_;
    AscendC::LocalTensor<float> gammaLocal_;
    AscendC::LocalTensor<float> betaLocal_;
    AscendC::LocalTensor<float> biasLocal_;
    AscendC::LocalTensor<float> biasRowLocalF_;
    AscendC::LocalTensor<float> x1Local_;
    AscendC::LocalTensor<float> x2Local_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> xAddLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> centeredLocal_;
};

// =========================================================================
// Strategy 3: splitd — preferred when N > 8192
// =========================================================================

template <typename dataType>
class AddLayerNormSplitDKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
        GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float eps, float invN,
        int64_t biasFlag, int64_t additionalOut, int64_t dtypeFlag)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->eps = eps;
        this->invN = invN;
        this->biasFlag = biasFlag;
        this->additionalOut = additionalOut;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Ptr), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Ptr), static_cast<uint64_t>(M) * N);
        biasGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(biasPtr),
            (biasFlag == 2) ? static_cast<uint64_t>(M) * N : N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gammaPtr), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(betaPtr), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yPtr), static_cast<uint64_t>(M) * N);
        xAddOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xAddOutPtr),
                                   static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
            pipe.InitBuffer(gammaInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
            pipe.InitBuffer(betaInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
            pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            pipe.InitBuffer(tempBuf_, kTileFloatBytes);
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(x1CastBuf_, kTileFloatBytes);
                pipe.InitBuffer(x2CastBuf_, kTileFloatBytes);
                pipe.InitBuffer(gammaCastBuf_, kTileFloatBytes);
                pipe.InitBuffer(betaCastBuf_, kTileFloatBytes);
                pipe.InitBuffer(biasCastBuf_, kBlockN * sizeof(float));
                pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
                pipe.InitBuffer(xAddCastBuf_, kTileFloatBytes);
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(M, blockM)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    static constexpr int kBlockN = 1024;
    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);

    __aicore__ inline int32_t NumTiles() const
    {
        return (N + kBlockN - 1) / kBlockN;
    }

    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
    }

    __aicore__ inline void CopyInX1(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                   static_cast<uint32_t>(validN));
        x1InQueue_.EnQue(x1InLocal_);
    }

    __aicore__ inline void CopyInX2(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                   static_cast<uint32_t>(validN));
        x2InQueue_.EnQue(x2InLocal_);
    }

    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
    {
        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
        LoadGmToUb(gammaInLocal_, gammaGM_[colBase], static_cast<uint32_t>(validN));
        gammaInQueue_.EnQue(gammaInLocal_);
    }

    __aicore__ inline void CopyInBeta(int32_t colBase, int32_t validN)
    {
        betaInLocal_ = betaInQueue_.AllocTensor<dataType>();
        LoadGmToUb(betaInLocal_, betaGM_[colBase], static_cast<uint32_t>(validN));
        betaInQueue_.EnQue(betaInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_,
                    static_cast<uint32_t>(validN));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void CopyOutXAdd(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
        StoreUbToGm(xAddOutGM_[static_cast<uint64_t>(rowIdx) * N + colBase], xAddOutLocal_,
                    static_cast<uint32_t>(validN));
        xAddOutQueue_.FreeTensor(xAddOutLocal_);
    }

    __aicore__ inline void LoadBiasTile(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        AscendC::LocalTensor<dataType> biasTyped;
        if (biasFlag == 1) {
            biasTyped = biasBuf_.Get<dataType>();
            LoadGmToUb(biasTyped, biasGM_[colBase], static_cast<uint32_t>(validN));
        } else if (biasFlag == 2) {
            biasTyped = biasBuf_.Get<dataType>();
            LoadGmToUb(biasTyped, biasGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        PrepareInputTensorHelper<dataType>(biasLocal_, biasTyped, biasCastBuf_, validN);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ComputeAddTile(int32_t validN)
    {
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, validN);
        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, validN);
        AscendC::Add(tempLocal_, x1Local_, x2Local_, validN);
        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
    }

    __aicore__ inline float ComputeMean(int32_t rowIdx)
    {
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        tempLocal_ = tempBuf_.Get<float>();
        float sumVal = 0.0f;

        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            CopyInX1(rowIdx, colBase, validN);
            CopyInX2(rowIdx, colBase, validN);
            ComputeAddTile(validN);

            // Add bias if present
            if (biasFlag == 1 || biasFlag == 2) {
                LoadBiasTile(rowIdx, colBase, validN);
                AscendC::Add(tempLocal_, tempLocal_, biasLocal_, validN);
            }

            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
            sumVal += sumLocal_.GetValue(0);
        }

        return sumVal * invN;
    }

    __aicore__ inline float ComputeInvStd(int32_t rowIdx, float meanVal)
    {
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        tempLocal_ = tempBuf_.Get<float>();
        float sumSq = 0.0f;

        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            CopyInX1(rowIdx, colBase, validN);
            CopyInX2(rowIdx, colBase, validN);
            ComputeAddTile(validN);

            if (biasFlag == 1 || biasFlag == 2) {
                LoadBiasTile(rowIdx, colBase, validN);
                AscendC::Add(tempLocal_, tempLocal_, biasLocal_, validN);
            }

            // centered = x_add - mean
            AscendC::Subs(tempLocal_, tempLocal_, meanVal, validN);
            AscendC::Mul(tempLocal_, tempLocal_, tempLocal_, validN);
            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
            sumSq += sumLocal_.GetValue(0);
        }

        float varVal = sumSq * invN + eps;
        return 1.0f / sqrtf(varVal);
    }

    __aicore__ inline void ApplyNorm(int32_t rowIdx, float meanVal, float invStd)
    {
        tempLocal_ = tempBuf_.Get<float>();
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            CopyInX1(rowIdx, colBase, validN);
            CopyInX2(rowIdx, colBase, validN);
            CopyInGamma(colBase, validN);
            CopyInBeta(colBase, validN);

            ComputeAddTile(validN);

            if (biasFlag == 1 || biasFlag == 2) {
                LoadBiasTile(rowIdx, colBase, validN);
                AscendC::Add(tempLocal_, tempLocal_, biasLocal_, validN);
            }

            // Store x_add if needed
            if (additionalOut) {
                xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
                PrepareOutputTensorHelper<dataType>(xAddLocal_, xAddOutLocal_, xAddCastBuf_);
                AscendC::Duplicate(xAddLocal_, tempLocal_, validN, 1, 1, 8);
                AscendC::PipeBarrier<PIPE_V>();
                FinalizeOutputTensorHelper<dataType>(xAddOutLocal_, xAddLocal_, validN);
                xAddOutQueue_.EnQue(xAddOutLocal_);
            }

            // Normalize: y = (x_add - mean) * inv_std
            AscendC::Subs(tempLocal_, tempLocal_, meanVal, validN);
            AscendC::Muls(tempLocal_, tempLocal_, invStd, validN);

            // affine: gamma * y + beta
            gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
            betaInLocal_ = betaInQueue_.DeQue<dataType>();
            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
            PrepareInputTensorHelper<dataType>(betaLocal_, betaInLocal_, betaCastBuf_, validN);
            AscendC::Mul(tempLocal_, tempLocal_, gammaLocal_, validN);
            AscendC::Add(tempLocal_, tempLocal_, betaLocal_, validN);
            gammaInQueue_.FreeTensor(gammaInLocal_);
            betaInQueue_.FreeTensor(betaInLocal_);

            FinalizeOutputTensorHelper<dataType>(yOutLocal_, tempLocal_, validN);
            yOutQueue_.EnQue(yOutLocal_);

            CopyOutY(rowIdx, colBase, validN);
            if (additionalOut) {
                CopyOutXAdd(rowIdx, colBase, validN);
            }

            // Prepare for next tile
            if (by + 1 < NumTiles()) {
                yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
                PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
            }
        }
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        const float meanVal = ComputeMean(rowIdx);
        const float invStd = ComputeInvStd(rowIdx, meanVal);
        ApplyNorm(rowIdx, meanVal, invStd);
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    int64_t biasFlag = 0;
    int64_t additionalOut = 0;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> xAddOutGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gammaInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> betaInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xAddOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xAddCastBuf_;

    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> gammaInLocal_;
    AscendC::LocalTensor<dataType> betaInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<dataType> xAddOutLocal_;
    AscendC::LocalTensor<float> x1Local_;
    AscendC::LocalTensor<float> x2Local_;
    AscendC::LocalTensor<float> gammaLocal_;
    AscendC::LocalTensor<float> betaLocal_;
    AscendC::LocalTensor<float> biasLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> xAddLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> tempLocal_;
};

// =========================================================================
// Shared dtype-dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchAddLayerNorm(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
    GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float eps, float invN,
    int64_t biasFlag, int64_t additionalOut, int64_t dtypeFlag,
    ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
                    M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN,
                    biasFlag, additionalOut, dtypeFlag);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
                    M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN,
                    biasFlag, additionalOut, dtypeFlag);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
                    M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN,
                    biasFlag, additionalOut, dtypeFlag);
        kernel.Process();
    }
}

