// AddLayerNorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
// Supports: x_add = x1 + x2 (+ bias) → LayerNorm

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_add_layer_norm_merge_n.h"
#include "aclrtlaunch_add_layer_norm_single_row.h"
#include "aclrtlaunch_add_layer_norm_splitd.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_ROW_FACTOR = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::vector<at::Tensor> add_layer_norm(
    const at::Tensor &x1,
    const at::Tensor &x2,
    const at::Tensor &bias,
    const at::Tensor &gamma,
    const at::Tensor &beta,
    double eps,
    bool additionalOut)
{
    TORCH_CHECK(x1.dim() == 2, "x1 must be 2D [M, N]");
    TORCH_CHECK(x2.dim() == 2, "x2 must be 2D [M, N]");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
    TORCH_CHECK(beta.dim() == 1, "beta must be 1D [N]");
    TORCH_CHECK(
        x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
            x1.scalar_type() == at::kBFloat16,
        "x1 must be float16, float32, or bfloat16");
    TORCH_CHECK(x2.scalar_type() == x1.scalar_type(),
        "x2 must have the same dtype as x1");
    TORCH_CHECK(gamma.scalar_type() == x1.scalar_type(),
        "gamma must have the same dtype as x1");
    TORCH_CHECK(beta.scalar_type() == x1.scalar_type(),
        "beta must have the same dtype as x1");
    TORCH_CHECK(x1.is_contiguous(), "x1 must be contiguous");
    TORCH_CHECK(x2.is_contiguous(), "x2 must be contiguous");
    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");

    int32_t M = static_cast<int32_t>(x1.sizes()[0]);
    int32_t N = static_cast<int32_t>(x1.sizes()[1]);

    // Process bias: determine biasFlag and bias tensor
    // biasFlag: -1 = no bias, 0 = broadcast from [N], 1 = per-row from [M, N]
    at::Tensor biasInput;
    int64_t biasFlag = -1;
    if (bias.defined()) {
        auto biasSizes = bias.sizes();
        if (biasSizes.size() == 1 && biasSizes[0] == static_cast<int64_t>(N)) {
            biasInput = bias.contiguous();
            biasFlag = 0;
            TORCH_CHECK(biasInput.scalar_type() == x1.scalar_type(),
                "bias must have the same dtype as x1");
        } else if (static_cast<int64_t>(biasSizes.size()) == 2 &&
                   biasSizes[0] == static_cast<int64_t>(M) &&
                   biasSizes[1] == static_cast<int64_t>(N)) {
            biasInput = bias.contiguous();
            biasFlag = 1;
            TORCH_CHECK(biasInput.scalar_type() == x1.scalar_type(),
                "bias must have the same dtype as x1");
        } else {
            TORCH_CHECK(false, "bias shape must be [N] or [M, N]");
        }
    } else {
        // Create dummy 1D bias for kernel
        biasInput = at::zeros({N}, x1.options());
        biasFlag = -1;
    }

    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Output tensors
    at::Tensor y = at::empty_like(x1);
    at::Tensor xAddOut = at::empty_like(x1);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x1.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x1.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    int64_t additionalOutFlag = additionalOut ? 1 : 0;

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t rowFactor = DEFAULT_ROW_FACTOR;
    float epsVal = static_cast<float>(eps);
    float invN = 1.0f / static_cast<float>(N);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Strategy dispatch: select kernel name and params
    if (N <= 1024) {
        EXEC_KERNEL_CMD(add_layer_norm_merge_n, blockDim,
                        x1, x2, biasInput, gamma, beta, y, xAddOut,
                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor,
                        epsVal, invN, biasFlag, additionalOutFlag, dtypeFlag);
    } else if (N > 8192) {
        EXEC_KERNEL_CMD(add_layer_norm_splitd, blockDim,
                        x1, x2, biasInput, gamma, beta, y, xAddOut,
                        M, N, blockM, usedCoreNum, tasksPerCore,
                        epsVal, invN, biasFlag, additionalOutFlag, dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(add_layer_norm_single_row, blockDim,
                        x1, x2, biasInput, gamma, beta, y, xAddOut,
                        M, N, blockM, usedCoreNum, tasksPerCore,
                        epsVal, invN, biasFlag, additionalOutFlag, dtypeFlag);
    }

    return {y, xAddOut};
}

}  // namespace ascend_kernel
