            static_cast<uint32_t>(N),
        };
        const uint32_t scaleSrcShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            1U,
        };
        const uint32_t scaleDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            static_cast<uint32_t>(N),
        };

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        scaleLocal_ = scaleBuf_.Get<float>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        meanTileLocal_ = meanTileBuf_.Get<float>();
        rstdTileLocal_ = rstdTileBuf_.Get<float>();

        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, tileSize);
        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, tileSize);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        // Step 1: x_add = x1 + x2
        AscendC::Add(yLocal_, x1Local_, x2Local_, tileSize);

        // Step 2: add bias if present
        if (biasFlag == 1) {
            // bias is [1, N] — we need to broadcast to [row_factor, N]
            // For merge_n, tileSize = row_factor * N
            // Use the pre-loaded biasLocal_[1, N] and broadcast
            meanBroadcastTmpLocal_ = meanBroadcastTmpBuf_.Get<uint8_t>();
            AscendC::Broadcast<float, 2, 1>(
                meanTileLocal_, biasLocal_, scaleDstShape, scaleSrcShape, meanBroadcastTmpLocal_);
            AscendC::Add(yLocal_, yLocal_, meanTileLocal_, tileSize);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocalF_, tileSize);
        }

        // Step 3: store x_add if needed
        if (additionalOut) {
            xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
            PrepareOutputTensorHelper<dataType>(xAddLocal_, xAddOutLocal_, xAddCastBuf_);
            AscendC::Duplicate(xAddLocal_, yLocal_, tileSize, 1, 1, 8);
            AscendC::PipeBarrier<PIPE_V>();
            FinalizeOutputTensorHelper<dataType>(xAddOutLocal_, xAddLocal_, tileSize);
            xAddOutQueue_.EnQue(xAddOutLocal_);
        }

        // Step 4: LayerNorm — mean = reduce_sum(y) / N
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);

        // Step 5: centered = y - mean, then squared
        AscendC::Broadcast<float, 2, 1>(
            meanTileLocal_, sumLocal_,
            scaleDstShape, scaleSrcShape, meanBroadcastTmpLocal_);
        AscendC::Sub(yLocal_, yLocal_, meanTileLocal_, tileSize);
        AscendC::Mul(yLocal_, yLocal_, yLocal_, tileSize);

        // Step 6: var = reduce_sum(centered^2) / N + eps
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);

        // Step 7: inv_std = 1/sqrt(var) — need scalar sqrt per row
        // Use Rsqrt directly for vectorized version
        AscendC::Rsqrt(rstdTileLocal_, sumLocal_, kMergeRowFactor);

        // Step 8: y = centered * inv_std * gamma + beta
        // Re-compute centered = x_add - mean (need to re-create x_add first)
        AscendC::Add(yLocal_, x1Local_, x2Local_, tileSize);
        if (biasFlag == 1) {
            meanBroadcastTmpLocal_ = meanBroadcastTmpBuf_.Get<uint8_t>();
            AscendC::Broadcast<float, 2, 1>(
                meanTileLocal_, biasLocal_, scaleDstShape, scaleSrcShape, meanBroadcastTmpLocal_);
            AscendC::Add(yLocal_, yLocal_, meanTileLocal_, tileSize);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocalF_, tileSize);
        }
        // Subtract mean
        AscendC::Broadcast<float, 2, 1>(
            meanTileLocal_, sumLocal_,
            scaleDstShape, scaleSrcShape, meanBroadcastTmpLocal_);
        // sumLocal_ still has mean values (from step 6, we added eps but need to reconstruct)
        // Actually we need the mean back. Let me restructure.
        // Better approach: save mean in a separate buffer
        // For now use the straightforward two-pass approach for merge_n:

        // Restart LayerNorm properly
        // Pass 1: compute mean
        AscendC::Add(yLocal_, x1Local_, x2Local_, tileSize);
        if (biasFlag == 1) {
            meanBroadcastTmpLocal_ = meanBroadcastTmpBuf_.Get<uint8_t>();
            AscendC::Broadcast<float, 2, 1>(
                meanTileLocal_, biasLocal_, scaleDstShape, scaleSrcShape, meanBroadcastTmpLocal_);
            AscendC::Add(yLocal_, yLocal_, meanTileLocal_, tileSize);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocalF_, tileSize);
        }
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);  // mean per row

        // Save mean, store x_add if needed
        AscendC::Duplicate(meanTileLocal_, sumLocal_, kMergeRowFactor, 1, 1, 8);
        AscendC::PipeBarrier<PIPE_V>();

        if (additionalOut) {
            xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
            PrepareOutputTensorHelper<dataType>(xAddLocal_, xAddOutLocal_, xAddCastBuf_);
            AscendC::Duplicate(xAddLocal_, yLocal_, tileSize, 1, 1, 8);
            AscendC::PipeBarrier<PIPE_V>();
            FinalizeOutputTensorHelper<dataType>(xAddOutLocal_, xAddLocal_, tileSize);
            xAddOutQueue_.EnQue(xAddOutLocal_);
        }

        // centered = y - mean
        AscendC::Broadcast<float, 2, 1>(
            rstdTileLocal_, meanTileLocal_,
            scaleDstShape, scaleSrcShape, rstdBroadcastTmpLocal_);
        AscendC::Sub(yLocal_, yLocal_, rstdTileLocal_, tileSize);

        // var = sum(centered^2) / N + eps
        AscendC::Mul(yLocal_, yLocal_, yLocal_, tileSize);
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);

        // inv_std = 1/sqrt(var), then broadcast
        AscendC::Rsqrt(rstdTileLocal_, sumLocal_, kMergeRowFactor);
        AscendC::Broadcast<float, 2, 1>(
            scaleLocal_, rstdTileLocal_,
            scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);

        // Re-create centered
        AscendC::Add(yLocal_, x1Local_, x2Local_, tileSize);
        if (biasFlag == 1) {
            meanBroadcastTmpLocal_ = meanBroadcastTmpBuf_.Get<uint8_t>();
            AscendC::Broadcast<float, 2, 1>(
                rstdTileLocal_, biasLocal_,
                scaleDstShape, scaleSrcShape, meanBroadcastTmpLocal_);
            AscendC::Add(yLocal_, yLocal_, rstdTileLocal_, tileSize);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocalF_, tileSize);
        }
        AscendC::Broadcast<float, 2, 1>(
            rstdTileLocal_, meanTileLocal_,
            scaleDstShape, scaleSrcShape, rstdBroadcastTmpLocal_);
        AscendC::Sub(yLocal_, yLocal_, rstdTileLocal_, tileSize);

        // y = centered * inv_std * gamma + beta
        AscendC::Mul(yLocal_, yLocal_, scaleLocal_, tileSize);
        AscendC::Mul(yLocal_, yLocal_, gammaTileLocal_, tileSize);
        AscendC::Add(yLocal_, yLocal_, betaTileLocal_, tileSize);
        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }", "replace_all": false}

