// AscendC AddLayerNorm kernel — merged strategies: merge_n, single_row, splitd
// Supports float32, float16, bfloat16
// Fuses: x_add = x1 + x2 (+ bias) → LayerNorm(x_add)
// Only merge_n and single_row are used (splitd is placeholder for future)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
{
    if (blockM == 0) { return 0; }
    return (M + blockM - 1) / blockM;
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void PrepareOutputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutputTensorHelper(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Strategy 1: single_row — one row at a time (used for N > 1024)
// =========================================================================

template <typename dataType>
class AddLayerNormSingleRowKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
        GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float eps, float invN,
        int64_t biasFlag, int64_t additionalOut)  // additionalOut not used here
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->eps = eps;
        this->invN = invN;
        this->biasFlag = biasFlag;
        this->additionalOut = additionalOut;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Ptr), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Ptr), static_cast<uint64_t>(M) * N);
        biasGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(biasPtr),
            (biasFlag == 2) ? static_cast<uint64_t>(M) * N : static_cast<uint64_t>(N));
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gammaPtr), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(betaPtr), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yPtr), static_cast<uint64_t>(M) * N);
        xAddOutGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(xAddOutPtr), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
            pipe.InitBuffer(betaBuf_, N * sizeof(dataType));
            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            pipe.InitBuffer(centeredBuf_, N * sizeof(float));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
                pipe.InitBuffer(betaCastBuf_, N * sizeof(float));
                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
            }

            // Pre-load gamma
            gammaInLocal_ = gammaBuf_.Get<dataType>();
            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);

            // Pre-load beta
            betaInLocal_ = betaBuf_.Get<dataType>();
            LoadGmToUb(betaInLocal_, betaGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            PrepareInputTensorHelper<dataType>(betaLocal_, betaInLocal_, betaCastBuf_, N);

            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(M, blockM)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX1(int32_t rowIdx)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x1InQueue_.EnQue(x1InLocal_);
    }

    __aicore__ inline void CopyInX2(int32_t rowIdx)
    {
        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x2InQueue_.EnQue(x2InLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        centeredLocal_ = centeredBuf_.Get<float>();

        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, N);
        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, N);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        // ===== Pass 1: x_add = x1 + x2 (+ bias), compute mean =====
        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
        // biasFlag: 1=broadcast [N], 2=per-row [M,N]
        if (biasFlag == 1) {
            AscendC::Add(yLocal_, yLocal_, biasBroadLocal_, N);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocal_, N);
        }

        // mean = sum(x_add) / N
        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
        float meanVal = sumLocal_.GetValue(0) * invN;

        // ===== If additionalOut, save x_add now =====
        // (simplified: skip x_add output for now; add later if needed)
        (void)additionalOut;

        // ===== Pass 2: centered = x_add - mean, compute var =====
        centeredLocal_ = centeredBuf_.Get<float>();
        AscendC::Adds(centeredLocal_, yLocal_, -meanVal, N);
        AscendC::Mul(yLocal_, centeredLocal_, centeredLocal_, N);
        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
        float varVal = sumLocal_.GetValue(0) * invN + eps;

        // inv_std = 1 / sqrt(var)
        float invStd = 1.0f / sqrt(varVal);

        // ===== Pass 3: normalize = (centered * inv_std) * gamma + beta =====
        AscendC::Muls(yLocal_, centeredLocal_, invStd, N);
        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
        AscendC::Add(yLocal_, yLocal_, betaLocal_, N);
        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        // Load bias for per-row mode
        if (biasFlag == 2) {
            AscendC::LocalTensor<dataType> bTyped = biasBuf_.Get<dataType>();
            LoadGmToUb(bTyped, biasGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            biasRowLocal_ = biasRowBuf_.Get<float>();
            PrepareInputTensorHelper<dataType>(biasRowLocal_, bTyped, biasCastBuf_, N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        CopyInX1(rowIdx);
        CopyInX2(rowIdx);
        ComputeRow();
        CopyOutY(rowIdx);
    }

    // Public for kernel init to pre-load broadcast bias
    __aicore__ inline void PreloadBroadcastBias()
    {
        if (biasFlag == 1) {
            AscendC::LocalTensor<dataType> bTyped = biasBuf_.Get<dataType>();
            LoadGmToUb(bTyped, biasGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            biasBroadLocal_ = biasCastBuf_.Get<float>();
            PrepareInputTensorHelper<dataType>(biasBroadLocal_, bTyped, biasCastBuf_, N);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    int64_t biasFlag = 0;
    int64_t additionalOut = 0;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> xAddOutGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasRowBuf_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> centeredBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> gammaInLocal_;
    AscendC::LocalTensor<dataType> betaInLocal_;
    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> gammaLocal_;
    AscendC::LocalTensor<float> betaLocal_;
    AscendC::LocalTensor<float> biasBroadLocal_;
    AscendC::LocalTensor<float> biasRowLocal_;
    AscendC::LocalTensor<float> x1Local_;
    AscendC::LocalTensor<float> x2Local_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> centeredLocal_;
};

// =========================================================================
// Strategy 2: merge_n — preferred when N <= 1024
// =========================================================================

template <typename dataType>
class AddLayerNormMergeNKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
        GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
        int64_t biasFlag, int64_t additionalOut)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->rowFactor = rowFactor;
        this->eps = eps;
        this->invN = invN;
        this->biasFlag = biasFlag;
        this->additionalOut = additionalOut;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Ptr), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Ptr), static_cast<uint64_t>(M) * N);
        biasGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(biasPtr),
            (biasFlag == 2) ? static_cast<uint64_t>(M) * N : static_cast<uint64_t>(N));
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gammaPtr), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(betaPtr), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yPtr), static_cast<uint64_t>(M) * N);
        xAddOutGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(xAddOutPtr), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
        rowLoops_ = subBlockRows_ / rowFactor;
        pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
        pipe.InitBuffer(betaBuf_, N * sizeof(dataType));
        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
        pipe.InitBuffer(gammaTileBuf_, kMergeRowFactor * N * sizeof(float));
        pipe.InitBuffer(betaTileBuf_, kMergeRowFactor * N * sizeof(float));
        pipe.InitBuffer(meanTileBuf_, kMergeRowFactor * N * sizeof(float));
        pipe.InitBuffer(rstdTileBuf_, kMergeRowFactor * N * sizeof(float));
        pipe.InitBuffer(gammaBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(betaBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(meanBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(rstdBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(x1CastBuf_, kMergeRowFactor * N * sizeof(float));
            pipe.InitBuffer(x2CastBuf_, kMergeRowFactor * N * sizeof(float));
            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
            pipe.InitBuffer(betaCastBuf_, N * sizeof(float));
            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
        }

        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
        const uint32_t gammaDstShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            static_cast<uint32_t>(N),
        };

        // Pre-load gamma and broadcast
        gammaInLocal_ = gammaBuf_.Get<dataType>();
        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
        gammaTileLocal_ = gammaTileBuf_.Get<float>();
        gammaBroadcastTmpLocal_ = gammaBroadcastTmpBuf_.Get<uint8_t>();
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Broadcast<float, 2, 0>(
            gammaTileLocal_, gammaLocal_, gammaDstShape, gammaSrcShape, gammaBroadcastTmpLocal_);

        // Pre-load beta and broadcast
        betaInLocal_ = betaBuf_.Get<dataType>();
        LoadGmToUb(betaInLocal_, betaGM_, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        PrepareInputTensorHelper<dataType>(betaLocal_, betaInLocal_, betaCastBuf_, N);
        betaTileLocal_ = betaTileBuf_.Get<float>();
        betaBroadcastTmpLocal_ = betaBroadcastTmpBuf_.Get<uint8_t>();
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Broadcast<float, 2, 0>(
            betaTileLocal_, betaLocal_, gammaDstShape, gammaSrcShape, betaBroadcastTmpLocal_);

        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(M, blockM)) {
                    continue;
                }

                for (int r = 0; r < rowLoops_; ++r) {
                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
                    const int validRows = M - rowBase;
                    if (validRows > 0) {
                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
                    }
                }
            }
        }
    }

private:
    static constexpr int kMergeRowFactor = 8;

    __aicore__ inline void CopyInX1(int32_t rowBase, int32_t count)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
        x1InQueue_.EnQue(x1InLocal_);
    }

    __aicore__ inline void CopyInX2(int32_t rowBase, int32_t count)
    {
        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
        x2InQueue_.EnQue(x2InLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeSingleRow()
    {
        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();

        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, N);
        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, N);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        // x_add = x1 + x2
        AscendC::Add(yLocal_, x1Local_, x2Local_, N);

        // bias (biasFlag: 1=preloaded broadcast, 2=per-row)
        if (biasFlag == 1) {
            AscendC::Add(yLocal_, yLocal_, biasBroadLocal_, N);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocal_, N);
        }

        // mean = sum / N
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
        float meanVal = sumLocal_.GetValue(0) * invN;

        // centered = x_add - mean
        AscendC::Adds(yLocal_, yLocal_, -meanVal, N);
        // Save centered for final pass (reuse yLocal_)
        AscendC::LocalTensor<float> saveCentered = rstdTileBuf_.Get<float>();
        // Copy centered to save buffer using vector add with zero
        AscendC::Duplicate(saveCentered, 0.0f, N);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(saveCentered, saveCentered, yLocal_, N);
        AscendC::PipeBarrier<PIPE_V>();

        // squared, reduce → var
        AscendC::Mul(yLocal_, yLocal_, yLocal_, N);
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
        float varVal = sumLocal_.GetValue(0) * invN + eps;
        float invStd = 1.0f / sqrt(varVal);

        // y = centered * inv_std * gamma + beta
        AscendC::Muls(yLocal_, saveCentered, invStd, N);
        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
        AscendC::Add(yLocal_, yLocal_, betaLocal_, N);
        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ComputeRows(int32_t tileSize)
    {
        const uint32_t reduceShape2D[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            static_cast<uint32_t>(N),
        };
        const uint32_t rowVecShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            1U,
        };
        const uint32_t tileShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            static_cast<uint32_t>(N),
        };

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        meanTileLocal_ = meanTileBuf_.Get<float>();
        rstdTileLocal_ = rstdTileBuf_.Get<float>();

        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, tileSize);
        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, tileSize);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        // === Pass 1: x_add = x1 + x2 (+ bias), compute mean ===
        AscendC::Add(yLocal_, x1Local_, x2Local_, tileSize);
        if (biasFlag == 1) {
            AscendC::Add(yLocal_, yLocal_, biasBroadLocal_, tileSize);
        } else if (biasFlag == 2) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocal_, tileSize);
        }

        // mean per row = reduce_sum / N
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape2D, true);
        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);

        // Save centered = x_add - mean in x1Local_ (reuse buffer)
        AscendC::Duplicate(meanTileLocal_, sumLocal_, kMergeRowFactor, 1, 1, 8);
        AscendC::PipeBarrier<PIPE_V>();
        meanBroadcastTmpLocal_ = meanBroadcastTmpBuf_.Get<uint8_t>();
        AscendC::Broadcast<float, 2, 1>(rstdTileLocal_, meanTileLocal_, tileShape, rowVecShape, meanBroadcastTmpLocal_);
        AscendC::Sub(x1Local_, yLocal_, rstdTileLocal_, tileSize);  // centered saved in x1Local_

        // === Pass 2: squared = centered^2, reduce → var → inv_std ===
        AscendC::Mul(yLocal_, x1Local_, x1Local_, tileSize);
        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape2D, true);
        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
        AscendC::Rsqrt(rstdTileLocal_, sumLocal_, kMergeRowFactor);

        // === Pass 3: broadcast inv_std, normalize ===
        rstdBroadcastTmpLocal_ = rstdBroadcastTmpBuf_.Get<uint8_t>();
        AscendC::Broadcast<float, 2, 1>(meanTileLocal_, rstdTileLocal_, tileShape, rowVecShape, rstdBroadcastTmpLocal_);
        AscendC::Mul(yLocal_, x1Local_, meanTileLocal_, tileSize);    // centered * inv_std
        AscendC::Mul(yLocal_, yLocal_, gammaTileLocal_, tileSize);     // * gamma
        AscendC::Add(yLocal_, yLocal_, betaTileLocal_, tileSize);      // + beta
        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessSingleRow(int rowIdx)
    {
        // Reload per-row bias
        if (biasFlag == 2) {
            LoadPerRowBias(rowIdx);
        }
        CopyInX1(rowIdx, N);
        CopyInX2(rowIdx, N);
        ComputeSingleRow();
        CopyOutY(rowIdx, N);
    }

    __aicore__ inline void ProcessRows(int rowBase, int validRows)
    {
        if (validRows < kMergeRowFactor) {
            for (int r = 0; r < validRows; ++r) {
                ProcessSingleRow(rowBase + r);
            }
            return;
        }

        // Reload per-row bias for each tile
        if (biasFlag == 2) {
            LoadPerRowBiasMulti(rowBase, kMergeRowFactor);
        }

        const int tileSize = kMergeRowFactor * N;
        CopyInX1(rowBase, tileSize);
        CopyInX2(rowBase, tileSize);
        ComputeRows(tileSize);
        CopyOutY(rowBase, tileSize);
    }

    __aicore__ inline void LoadPerRowBias(int32_t rowIdx)
    {
        AscendC::LocalTensor<dataType> bTyped = biasBuf_.Get<dataType>();
        LoadGmToUb(bTyped, biasGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        biasRowLocal_ = biasRowBuf_.Get<float>();
        PrepareInputTensorHelper<dataType>(biasRowLocal_, bTyped, biasCastBuf_, N);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void LoadPerRowBiasMulti(int32_t rowBase, int32_t numRows)
    {
        AscendC::LocalTensor<dataType> bTyped = biasBuf_.Get<dataType>();
        LoadGmToUb(bTyped, biasGM_[static_cast<uint64_t>(rowBase) * N],
                   static_cast<uint32_t>(numRows * N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        biasRowLocal_ = biasRowBuf_.Get<float>();
        PrepareInputTensorHelper<dataType>(biasRowLocal_, bTyped, biasCastBuf_, numRows * N);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // Preload broadcast bias (call from entry point)
    __aicore__ inline void PreloadBroadcastBias()
    {
        if (biasFlag == 1) {
            AscendC::LocalTensor<dataType> bTyped = biasBuf_.Get<dataType>();
            LoadGmToUb(bTyped, biasGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            biasBroadLocal_ = biasBroadBuf_.Get<float>();
            PrepareInputTensorHelper<dataType>(biasBroadLocal_, bTyped, biasCastBuf_, N);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t rowFactor = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    int64_t biasFlag = 0;
    int64_t additionalOut = 0;
    int subBlockRows_ = 0;
    int rowLoops_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> xAddOutGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasRowBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBroadBuf_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> meanTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rstdTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBroadcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBroadcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> meanBroadcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rstdBroadcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCastBuf_;
