template <typename dataType>
class AddLayerNormSplitDKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
        GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float eps, float invN,
        int64_t biasFlag, int64_t additionalOut)
    {
        // For N > 8192, fall back to single_row processing (one row at a time still works)
        innerKernel_.Init(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
                         M, N, blockM, usedCoreNum, tasksPerCore, eps, invN,
                         biasFlag, additionalOut);
    }

    __aicore__ inline void Process()
    {
        innerKernel_.Process();
    }

private:
    AddLayerNormSingleRowKernel<dataType> innerKernel_;
};

