template <typename dataType>
__aicore__ inline void RunAddLayerNormMergeN(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
    GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
    int64_t biasFlag, int64_t additionalOut)
{
    AddLayerNormMergeNKernel<dataType> kernel;
    kernel.Init(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
                M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, eps, invN,
                biasFlag, additionalOut);
    kernel.PreloadBroadcastBias();
    kernel.Process();
}

template <typename dataType>
__aicore__ inline void RunAddLayerNormSingleRow(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
