{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under BSD-3.
 *
 * AscendC AddLayerNorm kernel - unified implementation handling all N sizes.
 * Uses single_row approach for all cases (one row at a time), avoiding UB
 * overflow that occurs in merge_n with multiple rows + dual inputs + bias.
 *
 * Fuses: x_add = x1 + x2 (+ bias) → LayerNorm(x_add)
 * Supports: float32, float16, bfloat16
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
{
    if (blockM == 0) { return 0; }
    return (M + blockM - 1) / blockM;
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// Prepare: typed → float32 (or reinterpret for float32)
template <typename T>
__aicore__ inline void CastInputToF32(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void FinalizeF32ToOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::LocalTensor<float> castTmp = castBuf.Get<float>();
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// AddLayerNorm kernel: single_row for all N sizes
// Minimal UB layout avoids overflow at large N (~8K)
// =========================================================================

template <typename dataType>
class AddLayerNormKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
        GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float eps, float invN,
        int64_t biasFlag, int64_t additionalOut)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->eps = eps;
        this->invN = invN;
        this->biasFlag = biasFlag;
        this->additionalOut = additionalOut;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Ptr), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Ptr), static_cast<uint64_t>(M) * N);
        biasGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(biasPtr),
            (biasFlag == 1) ? static_cast<uint64_t>(M) * N : static_cast<uint64_t>(N));
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gammaPtr), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(betaPtr), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yPtr), static_cast<uint64_t>(M) * N);
        xAddOutGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(xAddOutPtr), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV {
            subBlockRows_ = blockM / AscendC::GetSubBlockNum();

            // UB buffers — tightly sized for N <= 8192:
            // Typed: x1In, x2In, yOut = 3 * N * sizeof(T)
            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
            // Float scratch: reduceBuf[N], centered[N], gamma/beta reuse castA afterwards
            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            // Cast buffers — shared across operations:
            // castA: x1 input, gamma loading
            // castB: x2 input, beta loading, output finalize
            // castC: bias (only when present), scratch for gamma/beta preloaded data
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(castA_, N * sizeof(float));
                pipe.InitBuffer(castB_, N * sizeof(float));
                if (biasFlag == 0 || biasFlag == 1) {
                    pipe.InitBuffer(castC_, N * sizeof(float));
                }
            }

            // Preload gamma into castA (reusing this buffer before row processing)
            if constexpr (!std::is_same_v<dataType, float>) {
                AscendC::LocalTensor<dataType> gammaTyped = gammaBuf_.Get<dataType>();
                LoadGmToUb(gammaTyped, gammaGM_, static_cast<uint32_t>(N));
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();
                gammaLocal_ = castA_.Get<float>();
                AscendC::Cast(gammaLocal_, gammaTyped, AscendC::RoundMode::CAST_NONE, N);
                AscendC::PipeBarrier<PIPE_V>();
            } else {
                AscendC::LocalTensor<dataType> gammaTyped = gammaBuf_.Get<dataType>();
                LoadGmToUb(gammaTyped, gammaGM_, static_cast<uint32_t>(N));
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();
                gammaLocal_ = gammaTyped.template ReinterpretCast<float>();
            }

            // Preload beta into castB
            if constexpr (!std::is_same_v<dataType, float>) {
                AscendC::LocalTensor<dataType> betaTyped = betaBuf_.Get<dataType>();
                LoadGmToUb(betaTyped, betaGM_, static_cast<uint32_t>(N));
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();
                betaLocal_ = castB_.Get<float>();
                AscendC::Cast(betaLocal_, betaTyped, AscendC::RoundMode::CAST_NONE, N);
                AscendC::PipeBarrier<PIPE_V>();
            } else {
                AscendC::LocalTensor<dataType> betaTyped = betaBuf_.Get<dataType>();
                LoadGmToUb(betaTyped, betaGM_, static_cast<uint32_t>(N));
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();
                betaLocal_ = betaTyped.template ReinterpretCast<float>();
            }

            // Preload broadcast bias into castC (if needed)
            if (biasFlag == 0) {
                if constexpr (!std::is_same_v<dataType, float>) {
                    AscendC::LocalTensor<dataType> biasTyped = biasBuf_.Get<dataType>();
                    LoadGmToUb(biasTyped, biasGM_, static_cast<uint32_t>(N));
                    AscendC::PipeBarrier<PIPE_MTE2>();
                    AscendC::PipeBarrier<PIPE_ALL>();
                    biasBroadLocal_ = castC_.Get<float>();
                    AscendC::Cast(biasBroadLocal_, biasTyped, AscendC::RoundMode::CAST_NONE, N);
                    AscendC::PipeBarrier<PIPE_V>();
                } else {
                    AscendC::LocalTensor<dataType> biasTyped = biasBuf_.Get<dataType>();
                    LoadGmToUb(biasTyped, biasGM_, static_cast<uint32_t>(N));
                    AscendC::PipeBarrier<PIPE_MTE2>();
                    AscendC::PipeBarrier<PIPE_ALL>();
                    biasBroadLocal_ = biasTyped.template ReinterpretCast<float>();
                }
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(M, blockM)) { continue; }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) { ProcessRow(rowIdx); }
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        // --- Load per-row bias if needed ---
        if (biasFlag == 1) {
            LoadPerRowBias(rowIdx);
        }

        // --- CopyIn x1, x2 ---
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x1InQueue_.EnQue(x1InLocal_);

        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        x2InQueue_.EnQue(x2InLocal_);

        // --- DeQue and cast ---
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        CastInputToF32<dataType>(x1Local_, x1InLocal_, castA_, N);

        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        CastInputToF32<dataType>(x2Local_, x2InLocal_, castB_, N);

        // --- Compute: x_add = x1 + x2 (+ bias) ---
        // Use yLocal_ as temporary accumulator (alloc from yOutQueue)
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            yLocal_ = yOutLocal_.template ReinterpretCast<float>();
        } else {
            yLocal_ = castB_.Get<float>();  // reuse castB for yLocal
        }

        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
        if (biasFlag == 0) {
            AscendC::Add(yLocal_, yLocal_, biasBroadLocal_, N);
        } else if (biasFlag == 1) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocal_, N);
        }

        // --- LayerNorm: mean ---
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
        float meanVal = sumLocal_.GetValue(0) * invN;

        // --- LayerNorm: var (using yLocal_ as workspace) ---
        // Maintain x1Local_ (original x1), x2Local_ (original x2) for recompute later
        // centered = x_add - mean, square, reduce
        AscendC::Adds(yLocal_, yLocal_, -meanVal, N);
        AscendC::Mul(yLocal_, yLocal_, yLocal_, N);
        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
        float varVal = sumLocal_.GetValue(0) * invN + eps;
        float invStd = 1.0f / sqrt(varVal);

        // --- Final output: recompute x_add, then normalize ---
        // yLocal_ = x_add again
        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
        if (biasFlag == 0) {
            AscendC::Add(yLocal_, yLocal_, biasBroadLocal_, N);
        } else if (biasFlag == 1) {
            AscendC::Add(yLocal_, yLocal_, biasRowLocal_, N);
        }
        // centered = x_add - mean
        AscendC::Adds(yLocal_, yLocal_, -meanVal, N);
        // y = centered * inv_std * gamma + beta
        AscendC::Muls(yLocal_, yLocal_, invStd, N);
        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
        AscendC::Add(yLocal_, yLocal_, betaLocal_, N);

        // Finalize: cast float32 → typed if needed, then CopyOut
        FinalizeF32ToOutput<dataType>(yOutLocal_, yLocal_, castB_, N);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        yOutQueue_.EnQue(yOutLocal_);

        // --- CopyOut y ---
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void LoadPerRowBias(int32_t rowIdx)
    {
        AscendC::LocalTensor<dataType> bTyped = biasBuf_.Get<dataType>();
        LoadGmToUb(bTyped, biasGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        if constexpr (!std::is_same_v<dataType, float>) {
            biasRowLocal_ = castC_.Get<float>();
            AscendC::Cast(biasRowLocal_, bTyped, AscendC::RoundMode::CAST_NONE, N);
            AscendC::PipeBarrier<PIPE_V>();
        } else {
            biasRowLocal_ = bTyped.template ReinterpretCast<float>();
        }
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float eps = 0.0f;
    float invN = 0.0f;
    int64_t biasFlag = 0;
    int64_t additionalOut = 0;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> xAddOutGM_;

    // Typed buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // Float scratch buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;

    // Shared cast buffers (float32)
    AscendC::TBuf<AscendC::TPosition::VECCALC> castA_;  // x1 input, gamma preload
    AscendC::TBuf<AscendC::TPosition::VECCALC> castB_;  // x2 input, beta preload, output finalize
    AscendC::TBuf<AscendC::TPosition::VECCALC> castC_;  // bias (conditional)

    // Local tensor views
    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> gammaLocal_;
    AscendC::LocalTensor<float> betaLocal_;
    AscendC::LocalTensor<float> biasBroadLocal_;
    AscendC::LocalTensor<float> biasRowLocal_;
    AscendC::LocalTensor<float> x1Local_;
    AscendC::LocalTensor<float> x2Local_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Kernel entry points — three strategies, all delegate to AddLayerNormKernel
// =========================================================================

template <typename dataType>
__aicore__ inline void RunAddLayerNorm(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
    GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float eps, float invN,
    int64_t biasFlag, int64_t additionalOut)
{
    AddLayerNormKernel<dataType> kernel;
    kernel.Init(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
                M, N, blockM, usedCoreNum, tasksPerCore, eps, invN,
                biasFlag, additionalOut);
    kernel.Process();
}

extern "C" __global__ __aicore__ void add_layer_norm_merge_n(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
    GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
    int64_t biasFlag, int64_t additionalOut, int64_t dtypeFlag)
{
    (void)rowFactor;  // unused in unified kernel
    if (dtypeFlag == 0) {
        RunAddLayerNorm<float>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    } else if (dtypeFlag == 1) {
        RunAddLayerNorm<half>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    } else {
        RunAddLayerNorm<bfloat16_t>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    }
}

extern "C" __global__ __aicore__ void add_layer_norm_single_row(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
    GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float eps, float invN,
    int64_t biasFlag, int64_t additionalOut, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        RunAddLayerNorm<float>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    } else if (dtypeFlag == 1) {
        RunAddLayerNorm<half>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    } else {
        RunAddLayerNorm<bfloat16_t>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    }
}

extern "C" __global__ __aicore__ void add_layer_norm_splitd(
    GM_ADDR x1Ptr, GM_ADDR x2Ptr, GM_ADDR biasPtr, GM_ADDR gammaPtr,
    GM_ADDR betaPtr, GM_ADDR yPtr, GM_ADDR xAddOutPtr,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float eps, float invN,
    int64_t biasFlag, int64_t additionalOut, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        RunAddLayerNorm<float>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    } else if (dtypeFlag == 1) {
        RunAddLayerNorm<half>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
    } else {
        RunAddLayerNorm<bfloat16_t>(x1Ptr, x2Ptr, biasPtr, gammaPtr, betaPtr, yPtr, xAddOutPtr,
            M, N, blockM, usedCoreNum, tasksPerCore, eps, invN, biasFlag, additionalOut);
