template <typename dataType>
class AddLayerNormKernel {
public:
    __aicore__ inline void Init(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR betap,
                                 GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm,
                                 int32_t ucn, int32_t tpc, float ep, float iN,
                                 int64_t bf, int64_t ao) {
        M_=M; N_=N; bm_=bm; ucn_=ucn; tpc_=tpc; ep_=ep; iN_=iN; bf_=bf; ao_=ao;
        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(x1p), static_cast<uint64_t>(M)*N);
        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(x2p), static_cast<uint64_t>(M)*N);
        bG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(bp), (bf==1)?static_cast<uint64_t>(M)*N:N);
        gG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(gp), N);
        beG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(betap), N);
        yG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(yp), static_cast<uint64_t>(M)*N);
        xAG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType*>(xap), static_cast<uint64_t>(M)*N);
        if ASCEND_IS_AIV { InitBufs(); }
    }

    __aicore__ inline void InitBufs() {
        sr_ = bm_ / AscendC::GetSubBlockNum();
        pipe.InitBuffer(sBuf_, N_ * sizeof(dataType));
        pipe.InitBuffer(q1_, BUFFER_NUM, N_ * sizeof(dataType));
        pipe.InitBuffer(q2_, BUFFER_NUM, N_ * sizeof(dataType));
        pipe.InitBuffer(qY_, BUFFER_NUM, N_ * sizeof(dataType));
        pipe.InitBuffer(rBuf_, N_ * sizeof(float));
        pipe.InitBuffer(cBuf_, N_ * sizeof(float));
        pipe.InitBuffer(smBuf_, 16 * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(cA_, N_ * sizeof(float));
            pipe.InitBuffer(cB_, N_ * sizeof(float));
            if (bf_ != -1) pipe.InitBuffer(cC_, N_ * sizeof(float));
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int si = AscendC::GetSubBlockIdx();
            for (int li=0; li<tpc_; ++li) {
                int bx = ci*tpc_+li;
                if (bx>=Blocks(M_,bm_)) continue;
                for (int r=0; r<sr_; ++r) {
                    int ri = bx*bm_+si*sr_+r;
                    if (ri<M_) ProcessRow(ri);
                }
            }
        }
    }

private:
    // Copy x1 + x2 from GM, return x_add in centeredBuf, also compute mean→val
    __aicore__ inline void LoadAddMean(int32_t ri, float &meanVal) {
        auto l1 = q1_.AllocTensor<dataType>(); LoadGm(l1, x1G_[static_cast<uint64_t>(ri)*N_], N_); q1_.EnQue(l1);
        auto l2 = q2_.AllocTensor<dataType>(); LoadGm(l2, x2G_[static_cast<uint64_t>(ri)*N_], N_); q2_.EnQue(l2);
        l1 = q1_.DeQue<dataType>(); CastIn<dataType>(xL_, l1, cA_, N_);
        l2 = q2_.DeQue<dataType>(); CastIn<dataType>(x2L_, l2, cB_, N_);
        cL_ = cBuf_.Get<float>();
        AscendC::Add(cL_, xL_, x2L_, N_);
        // bias
        if (bf_ == 0) AscendC::Add(cL_, cL_, bBr_, N_);
        else if (bf_ == 1) {
            auto bt = sBuf_.Get<dataType>(); LoadGm(bt, bG_[static_cast<uint64_t>(ri)*N_], N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            if constexpr (std::is_same_v<dataType,float>) bR_ = bt.template ReinterpretCast<float>();
            else { bR_ = cC_.Get<float>(); AscendC::Cast(bR_, bt, AscendC::RoundMode::CAST_NONE, N_);
                   AscendC::PipeBarrier<PIPE_V>(); }
            AscendC::Add(cL_, cL_, bR_, N_);
        }
        // mean
        rL_ = rBuf_.Get<float>(); sL_ = smBuf_.Get<float>();
        AscendC::ReduceSum<float>(sL_, cL_, rL_, N_);
        meanVal = sL_.GetValue(0) * iN_;
        // centered = x_add - mean
        AscendC::Adds(cL_, cL_, -meanVal, N_);
    }

    __aicore__ inline void ProcessRow(int32_t ri) {
        // Pass 1: load x1+x2, compute x_add, mean, centered in cBuf_
        float meanVal;
        LoadAddMean(ri, meanVal);

        // Pass 2: var = sum(centered^2)/N+eps → invStd
        AscendC::Mul(xL_, cL_, cL_, N_);           // xL_ (cA_) = centered^2
        AscendC::ReduceSum<float>(sL_, xL_, rL_, N_);
        float varVal = sL_.GetValue(0) * iN_ + ep_;
        float invStd = 1.0f / sqrt(varVal);

        // Pass 3: load gamma→cB_, compute output in cA_
        // xL_ (cA_) reused for output computation
        LoadGammaBeta();
        AscendC::Muls(xL_, cL_, invStd, N_);       // xL_ = centered * invStd
        AscendC::Mul(xL_, xL_, gL_, N_);           // xL_ *= gamma  (gL_ in cB_)
        // Now load beta → cB_
        auto bt = sBuf_.Get<dataType>();
        LoadGm(bt, beG_, N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        if constexpr (std::is_same_v<dataType,float>) beL_ = bt.template ReinterpretCast<float>();
        else { beL_ = cB_.Get<float>(); AscendC::Cast(beL_, bt, AscendC::RoundMode::CAST_NONE, N_);
               AscendC::PipeBarrier<PIPE_V>(); }
        AscendC::Add(xL_, xL_, beL_, N_);           // xL_ += beta

        // CopyOut
        auto y = qY_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType,float>) {
            auto yf = y.template ReinterpretCast<float>();
            AscendC::Adds(yf, xL_, 0.0f, N_);
        } else {
            AscendC::Cast(y, xL_, OutRound<dataType>(), N_);
            AscendC::PipeBarrier<PIPE_V>();
        }
        qY_.EnQue(y);
        q1_.FreeTensor(q1_.DeQue<dataType>());  // dummy: x1In already DeQue'd above
        xL_ = nullptr;  // don't use after this

        y = qY_.DeQue<dataType>();
        StoreGm(yG_[static_cast<uint64_t>(ri)*N_], y, N_);
        qY_.FreeTensor(y);
    }

    __aicore__ inline void LoadGammaBeta() {
        auto bt = sBuf_.Get<dataType>();
        LoadGm(bt, gG_, N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        if constexpr (std::is_same_v<dataType,float>) gL_ = bt.template ReinterpretCast<float>();
        else { gL_ = cB_.Get<float>(); AscendC::Cast(gL_, bt, AscendC::RoundMode::CAST_NONE, N_);
               AscendC::PipeBarrier<PIPE_V>(); }
    }

private:
    int32_t M_=0, N_=0, bm_=0, ucn_=0, tpc_=0, sr_=0;
    float ep_=0, iN_=0;
    int64_t bf_=-1, ao_=0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> x1G_, x2G_, bG_, gG_, beG_, yG_, xAG_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sBuf_, rBuf_, cBuf_, smBuf_, cA_, cB_, cC_;
    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> q1_, q2_;
    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> qY_;
    AscendC::LocalTensor<float> xL_, x2L_, cL_, gL_, beL_, bBr_, bR_, rL_, sL_;
};

