#include "kernel_operator.h"

constexpr int32_t BN = 1;  // buffer num (single-buffer, no double buffering)

__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
    return b ? (a + b - 1U) / b : 0U;
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutRnd() {
    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
static __aicore__ inline void DMAin(AscendC::LocalTensor<T> &d, AscendC::GlobalTensor<T> s, uint32_t n) {
    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(d, s, p, pp);
}
template <typename T>
static __aicore__ inline void DMAout(AscendC::GlobalTensor<T> d, AscendC::LocalTensor<T> &s, uint32_t n) {
    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(d, s, p);
}
static __aicore__ inline int32_t BlkCnt(int32_t M, int32_t bm) { return bm ? (M+bm-1)/bm : 0; }

template <typename T, typename B>
static __aicore__ inline void ToF32(AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
                                    B &cb, int32_t n) {
    if constexpr (std::is_same_v<T, float>) d = s.template ReinterpretCast<float>();
    else { d = cb.template Get<float>(); AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
           AscendC::PipeBarrier<PIPE_V>(); }
}

// ===== single-row AddLayerNorm kernel =====
template <typename T>
class AddLNKernel {
public:
    __aicore__ inline void Init(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
                                 GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm,
                                 int32_t ucn, int32_t tpc, float ep, float iN,
                                 int64_t bf, int64_t ao) {
        M_=M; N_=N; bm_=bm; ucn_=ucn; tpc_=tpc; ep_=ep; iN_=iN; bf_=bf; ao_=ao;
        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x1p), (uint64_t)M*N);
        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x2p), (uint64_t)M*N);
        bG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bp),  (bf==1)?(uint64_t)M*N:(uint64_t)N);
        gG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gp),  N);
        bg_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bep), N);
        yG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(yp),  (uint64_t)M*N);
        xaG_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xap), (uint64_t)M*N);
        if ASCEND_IS_AIV { InitBufs(); }
    }

    // Preload broadcast bias (call once before Process if bf==0)
    __aicore__ inline void PreloadBB() {
        if (bf_ != 0) return;
        auto bt = sB_.template Get<T>();
        DMAin(bt, bG_, N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        ToF32<T>(bB_, bt, cC_, N_);
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int si = AscendC::GetSubBlockIdx();
            for (int li=0; li<tpc_; ++li) {
                int bx = ci*tpc_+li;
                if (bx>=BlkCnt(M_,bm_)) continue;
                for (int r=0; r<sr_; ++r) {
                    int ri = bx*bm_+si*sr_+r;
                    if (ri<M_) DoRow(ri);
                }
            }
        }
    }

private:
    __aicore__ inline void InitBufs() {
        sr_ = bm_ / AscendC::GetSubBlockNum();
        pipe.InitBuffer(sB_,  N_ * sizeof(T));       // shared gamma/beta/bias typed stream
        pipe.InitBuffer(q1_,  BN, N_ * sizeof(T));   // x1 input
        pipe.InitBuffer(q2_,  BN, N_ * sizeof(T));   // x2 input
        pipe.InitBuffer(qY_,  BN, N_ * sizeof(T));   // output
        pipe.InitBuffer(rB_,  N_ * sizeof(float));   // reduce scratch
        pipe.InitBuffer(cB_,  N_ * sizeof(float));   // centered accumulator
        pipe.InitBuffer(sm_,  16 * sizeof(float));   // scalar sum
        if constexpr (!std::is_same_v<T, float>) {
            pipe.InitBuffer(cA_, N_ * sizeof(float)); // cast x1 / output workspace
            pipe.InitBuffer(cB2_,N_ * sizeof(float)); // cast x2 / gamma / beta
            if (bf_ != -1) pipe.InitBuffer(cC_, N_ * sizeof(float)); // bias cast
        }
    }

    // ==== main row computation ====
    __aicore__ inline void DoRow(int32_t ri) {
        // --- CopyIn x1, x2 ---
        auto x1t = q1_.AllocTensor<T>(); DMAin(x1t, x1G_[(uint64_t)ri*N_], N_); q1_.EnQue(x1t);
        auto x2t = q2_.AllocTensor<T>(); DMAin(x2t, x2G_[(uint64_t)ri*N_], N_); q2_.EnQue(x2t);
        x1t = q1_.DeQue<T>(); ToF32<T>(x1_, x1t, cA_, N_);
        x2t = q2_.DeQue<T>(); ToF32<T>(x2_, x2t, cB2_, N_);

        // --- x_add = x1 + x2 (+ bias) ---
        c_ = cB_.Get<float>();
        AscendC::Add(c_, x1_, x2_, N_);
        if (bf_ == 0)      AscendC::Add(c_, c_, bB_, N_);
        else if (bf_ == 1) { LoadRowBias(ri); AscendC::Add(c_, c_, bR_, N_); }

        // --- mean = sum / N ---
        r_ = rB_.Get<float>();    s_ = sm_.Get<float>();
        AscendC::ReduceSum<float>(s_, c_, r_, N_);
        float mean = s_.GetValue(0) * iN_;

        // --- centered = x_add - mean (in-place on c_) ---
        AscendC::Adds(c_, c_, -mean, N_);

        // --- var: squared in x1_ (cA_, reusing x1) ---
        AscendC::Mul(x1_, c_, c_, N_);          // x1_ = centered^2
        AscendC::ReduceSum<float>(s_, x1_, r_, N_);
        float var = s_.GetValue(0) * iN_ + ep_;
        float is  = 1.0f / sqrt(var);

        // --- load gamma → cB2_ (x2 done, free to reuse) ---
        {
            auto bt = sB_.Get<T>(); DMAin(bt, gG_, N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            ToF32<T>(g_, bt, cB2_, N_);
        }

        // --- y = centered * invStd * gamma ---
        AscendC::Muls(x1_, c_, is, N_);          // x1_ = centered * invStd
        AscendC::Mul (x1_, x1_, g_, N_);          // x1_ *= gamma

        // --- load beta → cB2_ ---
        {
            auto bt = sB_.Get<T>(); DMAin(bt, bg_, N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            ToF32<T>(b_, bt, cB2_, N_);
        }
        AscendC::Add(x1_, x1_, b_, N_);           // x1_ += beta

        // --- CopyOut ---
        auto yo = qY_.AllocTensor<T>();
        if constexpr (std::is_same_v<T, float>) {
            AscendC::Adds(yo.template ReinterpretCast<float>(), x1_, 0.0f, N_);
        } else {
            AscendC::Cast(yo, x1_, OutRnd<T>(), N_);
            AscendC::PipeBarrier<PIPE_V>();
        }
        qY_.EnQue(yo);
        q1_.FreeTensor(x1t); q2_.FreeTensor(x2t);

        yo = qY_.DeQue<T>(); DMAout(yG_[(uint64_t)ri*N_], yo, N_); qY_.FreeTensor(yo);
    }

    __aicore__ inline void LoadRowBias(int32_t ri) {
        auto bt = sB_.Get<T>(); DMAin(bt, bG_[(uint64_t)ri*N_], N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        ToF32<T>(bR_, bt, cC_, N_);
    }

private:
    int32_t M_=0, N_=0, bm_=0, ucn_=0, tpc_=0, sr_=0;
    float ep_=0.f, iN_=0.f;
    int64_t bf_=-1, ao_=0;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<T> x1G_, x2G_, bG_, gG_, bg_, yG_, xaG_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sB_, rB_, cB_, sm_, cA_, cB2_, cC_;
    AscendC::TQue<AscendC::TPosition::VECIN,BN>  q1_, q2_;
    AscendC::TQue<AscendC::TPosition::VECOUT,BN> qY_;
    AscendC::LocalTensor<float> x1_, x2_, c_, g_, b_, bB_, bR_, r_, s_;
};

// ===== entry points (3 strategies, all delegate to same kernel) =====

template <typename T>
static __aicore__ inline void RunKernel(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
    GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm, int32_t ucn, int32_t tpc,
    float ep, float iN, int64_t bf, int64_t ao) {
    AddLNKernel<T> k;
    k.Init(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
    k.PreloadBB();
    k.Process();
}

