19	
20	constexpr int32_t BN = 1;  // buffer num (single-buffer, no double buffering)
21	
22	__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
23	    return b ? (a + b - 1U) / b : 0U;
24	}
25	
26	template <typename T>
27	__aicore__ inline AscendC::RoundMode OutRnd() {
28	    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
29	    return AscendC::RoundMode::CAST_NONE;
30	}
31	
32	template <typename T>
33	static __aicore__ inline void DMAin(AscendC::LocalTensor<T> &d, AscendC::GlobalTensor<T> s, uint32_t n) {
34	    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
35	    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
36	    AscendC::DataCopyPad(d, s, p, pp);
37	}
38	template <typename T>
39	static __aicore__ inline void DMAout(AscendC::GlobalTensor<T> d, AscendC::LocalTensor<T> &s, uint32_t n) {
40	    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
41	    AscendC::DataCopyPad(d, s, p);
42	}
43	static __aicore__ inline int32_t BlkCnt(int32_t M, int32_t bm) { return bm ? (M+bm-1)/bm : 0; }
44	
45	template <typename T, typename B>
46	static __aicore__ inline void ToF32(AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
47	                                    B &cb, int32_t n) {
48	    if constexpr (std::is_same_v<T, float>) d = s.template ReinterpretCast<float>();
49	    else { d = cb.template Get<float>(); AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
50	           AscendC::PipeBarrier<PIPE_V>(); }
51	}
