53	// ===== single-row AddLayerNorm kernel =====
54	template <typename T>
55	class AddLNKernel {
56	public:
57	    __aicore__ inline void Init(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
58	                                 GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm,
59	                                 int32_t ucn, int32_t tpc, float ep, float iN,
60	                                 int64_t bf, int64_t ao) {
61	        M_=M; N_=N; bm_=bm; ucn_=ucn; tpc_=tpc; ep_=ep; iN_=iN; bf_=bf; ao_=ao;
62	        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x1p), (uint64_t)M*N);
63	        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x2p), (uint64_t)M*N);
64	        bG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bp),  (bf==1)?(uint64_t)M*N:(uint64_t)N);
65	        gG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gp),  N);
66	        bg_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bep), N);
67	        yG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(yp),  (uint64_t)M*N);
68	        xaG_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xap), (uint64_t)M*N);
69	        if ASCEND_IS_AIV { InitBufs(); }
70	    }
71	
72	    // Preload broadcast bias (call once before Process if bf==0)
73	    __aicore__ inline void PreloadBB() {
74	        if (bf_ != 0) return;
75	        auto bt = sB_.template Get<T>();
76	        DMAin(bt, bG_, N_);
77	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
78	        ToF32<T>(bB_, bt, cC_, N_);
79	    }
80	
81	    __aicore__ inline void Process() {
82	        if ASCEND_IS_AIV {
83	            int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
84	            int si = AscendC::GetSubBlockIdx();
85	            for (int li=0; li<tpc_; ++li) {
86	                int bx = ci*tpc_+li;
87	                if (bx>=BlkCnt(M_,bm_)) continue;
88	                for (int r=0; r<sr_; ++r) {
89	                    int ri = bx*bm_+si*sr_+r;
90	                    if (ri<M_) DoRow(ri);
91	                }
92	            }
93	        }
94	    }
95	
96	private:
97	    __aicore__ inline void InitBufs() {
98	        sr_ = bm_ / AscendC::GetSubBlockNum();
99	        pipe.InitBuffer(sB_,  N_ * sizeof(T));       // shared gamma/beta/bias typed stream
100	        pipe.InitBuffer(qI_,  BN, N_ * sizeof(T));   // shared input (x1 then x2 sequentially)
101	        pipe.InitBuffer(qY_,  BN, N_ * sizeof(T));   // output
102	        pipe.InitBuffer(rB_,  N_ * sizeof(float));   // reduce scratch
103	        pipe.InitBuffer(cB_,  N_ * sizeof(float));   // centered accumulator
104	        pipe.InitBuffer(sm_,  16 * sizeof(float));   // scalar sum
105	        pipe.InitBuffer(cA_, N_ * sizeof(float));       // x1 workspace (cast or copy)
106	        pipe.InitBuffer(cB2_,N_ * sizeof(float));       // x2/gamma/beta workspace
107	        if (bf_ != -1) {
108	            if constexpr (!std::is_same_v<T, float>)
109	                pipe.InitBuffer(cC_, N_ * sizeof(float)); // bias cast
110	            else
111	                pipe.InitBuffer(cC_, N_ * sizeof(float)); // bias copy workspace (float32)
112	        }
113	    }
114	
115	    // ==== main row computation ====
116	    __aicore__ inline void DoRow(int32_t ri) {
117	        // --- CopyIn x1 into qI_, cast to cA_ ---
118	        auto x1t = qI_.AllocTensor<T>(); DMAin(x1t, x1G_[(uint64_t)ri*N_], N_); qI_.EnQue(x1t);
119	        x1t = qI_.DeQue<T>(); ToF32<T>(x1_, x1t, cA_, N_); qI_.FreeTensor(x1t);
120	        // --- CopyIn x2 into same qI_, cast to cB2_ ---
121	        auto x2t = qI_.AllocTensor<T>(); DMAin(x2t, x2G_[(uint64_t)ri*N_], N_); qI_.EnQue(x2t);
122	        x2t = qI_.DeQue<T>(); ToF32<T>(x2_, x2t, cB2_, N_); qI_.FreeTensor(x2t);
123	
124	        // --- x_add = x1 + x2 (+ bias) ---
125	        c_ = cB_.Get<float>();
126	        AscendC::Add(c_, x1_, x2_, N_);
127	        if (bf_ == 0)      AscendC::Add(c_, c_, bB_, N_);
128	        else if (bf_ == 1) { LoadRowBias(ri); AscendC::Add(c_, c_, bR_, N_); }
129	
130	        // --- mean = sum / N ---
131	        r_ = rB_.Get<float>();    s_ = sm_.Get<float>();
132	        AscendC::ReduceSum<float>(s_, c_, r_, N_);
133	        float mean = s_.GetValue(0) * iN_;
134	
135	        // --- centered = x_add - mean (in-place on c_) ---
136	        AscendC::Adds(c_, c_, -mean, N_);
137	
138	        // --- var: squared in x1_ (cA_, reusing x1) ---
139	        AscendC::Mul(x1_, c_, c_, N_);          // x1_ = centered^2
140	        AscendC::ReduceSum<float>(s_, x1_, r_, N_);
141	        float var = s_.GetValue(0) * iN_ + ep_;
142	        float is  = 1.0f / sqrt(var);
143	
144	        // --- load gamma → cB2_ (x2 done, free to reuse) ---
145	        {
146	            auto bt = sB_.Get<T>(); DMAin(bt, gG_, N_);
147	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
148	            ToF32<T>(g_, bt, cB2_, N_);
149	        }
150	
151	        // --- y = centered * invStd * gamma ---
152	        AscendC::Muls(x1_, c_, is, N_);          // x1_ = centered * invStd
153	        AscendC::Mul (x1_, x1_, g_, N_);          // x1_ *= gamma
154	
155	        // --- load beta → cB2_ ---
156	        {
157	            auto bt = sB_.Get<T>(); DMAin(bt, bg_, N_);
158	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
159	            ToF32<T>(b_, bt, cB2_, N_);
160	        }
161	        AscendC::Add(x1_, x1_, b_, N_);           // x1_ += beta
162	
163	        // --- CopyOut ---
164	        auto yo = qY_.AllocTensor<T>();
165	        if constexpr (std::is_same_v<T, float>) {
166	            AscendC::Adds(yo.template ReinterpretCast<float>(), x1_, 0.0f, N_);
167	        } else {
168	            AscendC::Cast(yo, x1_, OutRnd<T>(), N_);
169	            AscendC::PipeBarrier<PIPE_V>();
170	        }
171	        qY_.EnQue(yo);
172	
173	        yo = qY_.DeQue<T>(); DMAout(yG_[(uint64_t)ri*N_], yo, N_); qY_.FreeTensor(yo);
174	    }
