176	    __aicore__ inline void LoadRowBias(int32_t ri) {
177	        auto bt = sB_.Get<T>(); DMAin(bt, bG_[(uint64_t)ri*N_], N_);
178	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
179	        ToF32<T>(bR_, bt, cC_, N_);
180	    }
