183	    int32_t M_=0, N_=0, bm_=0, ucn_=0, tpc_=0, sr_=0;
184	    float ep_=0.f, iN_=0.f;
185	    int64_t bf_=-1, ao_=0;
186	    AscendC::TPipe pipe;
187	    AscendC::GlobalTensor<T> x1G_, x2G_, bG_, gG_, bg_, yG_, xaG_;
188	    AscendC::TBuf<AscendC::TPosition::VECCALC> sB_, rB_, cB_, sm_, cA_, cB2_, cC_;
189	    AscendC::TQue<AscendC::TPosition::VECIN,BN>  qI_;
190	    AscendC::TQue<AscendC::TPosition::VECOUT,BN> qY_;
191	    AscendC::LocalTensor<float> x1_, x2_, c_, g_, b_, bB_, bR_, r_, s_;
192	};
