196	template <typename T>
197	static __aicore__ inline void RunKernel(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
198	    GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm, int32_t ucn, int32_t tpc,
199	    float ep, float iN, int64_t bf, int64_t ao) {
200	    AddLNKernel<T> k;
201	    k.Init(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
202	    k.PreloadBB();
203	    k.Process();
204	}
